import { useCallback } from 'react';
import { UserParams } from '~/entities/user/api/dtos/types';
import { useGetUserInfoQuery } from '~/entities/user/api/use-get-cstmr-query';
import { useUpdateUserInfo } from '~/entities/user/lib/use-update-user-info';
import { YesOrNo } from '~/shared/api/dtos/enums';
import { ToggleSwitch } from '~/shared/ui/toggle-switch/toggle-switch';

export const ToggleAllNotification = () => {
  const { data: userRes } = useGetUserInfoQuery();
  const { updateUserInfo } = useUpdateUserInfo();

  const { processNtcnYn, transfrNtcnYn, etcNtcnYn } = userRes?.tbCstmrMastr;

  const onToggleAll = useCallback(() => {
    const allChk = ['processNtcnYn', 'transfrNtcnYn', 'etcNtcnYn'].every(
      (key) => userRes?.tbCstmrMastr[key as keyof UserParams] === YesOrNo.예,
    )
      ? YesOrNo.아니오
      : YesOrNo.예;

    updateUserInfo({
      processNtcnYn: allChk,
      transfrNtcnYn: allChk,
      etcNtcnYn: allChk,
    });
  }, [userRes?.tbCstmrMastr]);
  return (
    <ToggleSwitch
      on={processNtcnYn === YesOrNo.예 && transfrNtcnYn === YesOrNo.예 && etcNtcnYn === YesOrNo.예}
      onToggle={onToggleAll}
    />
  );
};
